def _bullets(items: list[str]) -> str:
    if not items:
        return "- (none)"
    return "\n".join(f"- {item}" for item in items)


def _numbered(items: list[str]) -> str:
    if not items:
        return "1. (none)"
    return "\n".join(f"{i}. {item}" for i, item in enumerate(items, start=1))


def render_markdown(brief: RepairBrief) -> str:
    h = _HEADERS[brief.language]
    lines = [
        f"# {h['title']}: {brief.device} — {brief.symptom}",
        "",
        f"**{h['difficulty']}:** {brief.difficulty.value} · "
        f"**{h['time']}:** {brief.estimated_time_minutes} {h['minutes']} · "
        f"**{h['generated_by']}:** {brief.generated_by}",
        "",
        f"## {h['summary']}",
        "",
        brief.summary,
        "",
        f"## {h['causes']}",
        "",
        _bullets(brief.likely_causes),
        "",
        f"## {h['diagnostic']}",
        "",
        _numbered(brief.diagnostic_steps),
        "",
        f"## {h['repair']}",
        "",
        _numbered(brief.repair_steps),
        "",
        f"## {h['tools']}",
        "",
        _bullets(brief.tools_needed),
        "",
        f"## {h['warnings']}",
        "",
        _bullets(brief.safety_warnings),
        "",
        f"## {h['sources']}",
        "",
    ]
    if brief.sources:
        lines.extend(f"- {s.title} ({s.kind}: {s.locator})" for s in brief.sources)
    else:
        lines.append("- (none)")
    lines.append("")
    return "\n".join(lines)
